// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract MockRoundImpl {
    function initialize(bytes calldata, address) external {}
}

contract InvMutTest is Test {
    RoundFactory c;
    MockRoundImpl impl;
    address constant ALLO = address(0xA110);

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
        impl = new MockRoundImpl();
        c.updateRoundImplementation(payable(address(impl)));
        c.updateAlloSettings(ALLO);
    }

    function _check(address caller) internal {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));

        bool created = false;
        vm.prank(caller);
        try c.create("", caller) returns (address) {
            created = true;
        } catch {
            created = false;
        }

        assertFalse(created, "unauthorized caller created a round");
    }

    function testFuzz_property(address caller) public {
        _check(caller);
    }
}
